import java.math.BigInteger;

class Solution {
  public boolean isAdditiveNumber(String num) {
    int n = num.length();
    for (int i = 1; i <= n / 2; i++) {
      if (num.charAt(0) == '0' && i > 1) break;
      for (int j = i + 1; n - j >= Math.max(i, j - i); j++) {
        if (num.charAt(i) == '0' && j > i + 1) break;
        if (valid(num, new BigInteger(num.substring(0, i)), new BigInteger(num.substring(i, j)), j)) return true;
      }
    }
    return false;
  }

  private boolean valid(String num, BigInteger a, BigInteger b, int start) {
    if (start == num.length()) return true;
    String sum = a.add(b).toString();
    return num.startsWith(sum, start) && valid(num, b, a.add(b), start + sum.length());
  }
}
